29	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, outcomeOf,
30	} from '../../../../engine/scheduler/queue/work-item.mjs';
31	
32	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
33	
34	// How far back the FIRST read looks with no mark yet — the day tier's own width, so
35	// one fold populates the whole window rather than starting it empty.
36	export const FIRST_READ_LOOKBACK_DAYS = 30;
37	
38	export const lookbackFrom = (nowIso, days = FIRST_READ_LOOKBACK_DAYS) =>
39	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
40	
41	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
42	  const headers = {
43	    accept: 'application/vnd.github+json',
44	    'x-github-api-version': '2022-11-28',
45	    'user-agent': 'claudinite-usage-fold',
46	    ...(token ? { authorization: `Bearer ${token}` } : {}),
47	  };
48	  return {
49	    async json(path) {
50	      const res = await fetchImpl(`${api}${path}`, { headers });
51	      if (res.status !== 200) return null;
52	      try { return await res.json(); } catch { return null; }
53	    },
54	  };
55	}
